#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ilen = 0, ipos = 0;

static inline int gc() {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof ibuf, stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return ibuf[ipos++];
}

static long long readInt() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long v = 0;
    while (c >= '0' && c <= '9') {
        v = v * 10 + (c - '0');
        c = gc();
    }
    return neg ? -v : v;
}

static string readToken() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    string s;
    while (c > ' ') {
        s.push_back((char)c);
        c = gc();
    }
    return s;
}

int main() {
    int n = (int)readInt();
    vector<long long> a(n);
    int last = -1;
    for (int i = 0; i < n; i++) {
        a[i] = readInt();
        if (a[i] == 0) last = i;
    }
    // A 1 before the last 0 always closes; 1s after it never do.
    vector<long long> kept;
    bool skip = false;
    for (int i = 0; i < n; i++) {
        long long v = a[i];
        if (v == 1 && i < last) skip = true;
        if (!skip) kept.push_back(v);
        if (v == 0) skip = false;
    }
    long long sum = 0;
    string out = to_string(kept.size()) + "\n";
    for (size_t i = 0; i < kept.size(); i++) {
        if (i) out.push_back(' ');
        out += to_string(kept[i]);
        sum += kept[i];
    }
    out += "\n" + to_string(sum);
    puts(out.c_str());
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        int last = -1;
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            if (a[i] == 0) last = i;
        }
        StringBuilder sb = new StringBuilder();
        boolean skip = false;
        int count = 0;
        long sum = 0;
        for (int i = 0; i < n; i++) {
            long v = a[i];
            if (v == 1 && i < last) skip = true;
            if (!skip) {
                if (count++ > 0) sb.append(' ');
                sb.append(v);
                sum += v;
            }
            if (v == 0) skip = false;
        }
        System.out.println(count + "\n" + sb + "\n" + sum);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	a := make([]int, n)
	last := -1
	for i := range a {
		a[i] = nextInt()
		if a[i] == 0 {
			last = i
		}
	}
	var sb strings.Builder
	skip := false
	count, sum := 0, 0
	for i, v := range a {
		if v == 1 && i < last {
			skip = true
		}
		if !skip {
			if count > 0 {
				sb.WriteByte(' ')
			}
			sb.WriteString(strconv.Itoa(v))
			count++
			sum += v
		}
		if v == 0 {
			skip = false
		}
	}
	fmt.Printf("%d\n%s\n%d\n", count, sb.String(), sum)
}
